let DATA;
const state={view:'research',rSearch:'',rFilter:'全部',rSector:'',rSort:'strengthPercentile20',rOrder:-1,exchange:'全部',sector:'全部',search:'',sort:'changePct',order:-1,selected:'au',period:40,rankMode:'increase',favorites:[]};
try{state.favorites=JSON.parse(localStorage.getItem('guanlan-favorites')||'[]');if(!Array.isArray(state.favorites))state.favorites=[]}catch{}
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const num=(x,d=0)=>x==null?'—':Number(x).toLocaleString('zh-CN',{minimumFractionDigits:d,maximumFractionDigits:d});
const signed=(x,d=0)=>x==null?'—':(x>0?'+':'')+num(x,d);
const color=x=>x>0?'up':x<0?'down':'neutral';
const exchangeNames={SHFE:'上期所',INE:'上期能源',DCE:'大商所',CZCE:'郑商所',GFEX:'广期所'};
const exLabel=()=>DATA.coverage.exchanges.map(x=>exchangeNames[x]||x).join('、');
const sourceOf=m=>m.quoteSource||{name:'上期所官方日行情',url:DATA.sources.quotes,date:DATA.asOf};
const validHistory=m=>m.history.filter(h=>Number.isFinite(h.close)&&h.close>0);
const isFixed=m=>!m.historyType||m.historyType==='fixed-contract';
const decimals=m=>m.unit==='元/克'||['sc','ec'].includes(m.code)?2:0;
const coverageText=m=>m.aggregateScope==='all-contracts'?'全合约合计':'代表合约样本';
const compact=x=>Math.abs(x)>=1e8?num(x/1e8,2)+'亿':Math.abs(x)>=1e4?num(x/1e4,2)+'万':num(x);
const mean=a=>a.length?a.reduce((s,x)=>s+x,0)/a.length:null;
function trend(m){if(m.analysis){const a=m.analysis;return {id:a.trendDirection===1?'bull':a.trendDirection===-1?'bear':a.trendDirection===0?'mixed':'unknown',name:a.trendLabel,class:a.trendDirection===1?'positive':a.trendDirection===-1?'negative':'',ma5:a.ma5,ma20:a.ma20}}const a=validHistory(m).map(h=>h.close);if(!isFixed(m))return {id:'unknown',name:'连续行情',class:'',ma5:null,ma20:null};if(a.length<20)return {id:'unknown',name:'样本不足',class:'',ma5:null,ma20:null};const ma5=mean(a.slice(-5)),ma20=mean(a.slice(-20)),last=a.at(-1);return {id:last>ma20&&ma5>ma20?'bull':last<ma20&&ma5<ma20?'bear':'mixed',name:last>ma20&&ma5>ma20?'趋势偏多':last<ma20&&ma5<ma20?'趋势偏空':'方向分化',class:last>ma20&&ma5>ma20?'positive':last<ma20&&ma5<ma20?'negative':'',ma5,ma20}}
function selected(){return DATA.markets.find(m=>m.code===state.selected)||DATA.markets[0]}
function spark(m,cls='mini-spark'){const a=validHistory(m).slice(-24).map(h=>h.close);if(a.length<2)return '';const lo=Math.min(...a),hi=Math.max(...a),range=hi-lo||1;const points=a.map((v,i)=>`${i*100/(a.length-1)},${28-(v-lo)/range*24}`).join(' ');const c=a.at(-1)>=a[0]?'#b86454':'#6d8a69';return `<svg class="${cls}" viewBox="0 0 100 32" preserveAspectRatio="none" aria-label="最近${a.length}个交易样本收盘价走势"><polyline points="${points}" fill="none" stroke="${c}" stroke-width="1.6" vector-effect="non-scaling-stroke"/></svg>`}
function marketSelect(){return `<select class="select" id="market-select" aria-label="选择研究品种">${DATA.markets.map(m=>`<option value="${m.code}" ${m.code===state.selected?'selected':''}>${esc(m.name)} · ${m.main.contract.toUpperCase()}</option>`).join('')}</select>`}
function heading(title,sub,kicker){return `<div class="page-heading"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p class="subtitle">${sub}</p></div><div class="page-buttons"><span class="btn date-label">◷ &nbsp; ${DATA.asOf} · 盘后</span><button class="btn btn-primary" id="export">↓ 导出数据</button></div></div>`}
function stat(label,value,unit,note,icon='↗'){return `<div class="stat"><div class="stat-label">${label}<span class="stat-icon">${icon}</span></div><div class="stat-value">${value}<small>${unit}</small></div><div class="stat-note">${note}</div></div>`}
function overview(){
 const ms=DATA.markets,up=ms.filter(m=>m.main.changePct>0).length,down=ms.filter(m=>m.main.changePct<0).length;
 const sorted=ms.filter(m=>m.main.changePct!=null).sort((a,b)=>b.main.changePct-a.main.changePct),leader=sorted[0],laggard=sorted.at(-1);
 const volumeRows=ms.filter(m=>m.totalVolume!=null&&m.aggregateScope==='all-contracts'),oiRows=ms.filter(m=>m.totalOiChange!=null&&m.aggregateScope==='all-contracts'),volume=volumeRows.reduce((s,m)=>s+m.totalVolume,0),oiChange=oiRows.reduce((s,m)=>s+m.totalOiChange,0);
 return heading('看见价格，也看见结构。','从趋势、成交与席位出发，跟踪境内商品市场的每日变化。','MARKET OBSERVATORY / 市场概览')+
 `<div class="brief"><div class="brief-label">DAILY BRIEF<strong>今日观察</strong></div><div class="brief-text"><h2>${esc(leader.name)}领涨，${esc(laggard.name)}承压。</h2><p>覆盖样本 ${up} 个品种上涨、${down} 个下跌。${esc(leader.name)} ${signed(leader.main.changePct,2)}%，${esc(laggard.name)} ${signed(laggard.main.changePct,2)}%；可核实昨结算价的品种参与涨跌比较。</p></div><a href="#trends" class="brief-arrow" aria-label="查看趋势全景">↗</a></div>`+
 `<div class="stats-grid">${stat('覆盖商品',ms.length,'个',`${DATA.coverage.exchanges.length} 家交易所 / 机构 · 已取得样本`,'⊞')}${stat('涨跌广度',`<span class="up">${up}</span><span style="font-size:18px;color:#c0c6b6"> / </span><span class="down">${down}</span>`,'涨 / 跌',`另有 ${ms.length-up-down} 个平盘或无涨跌样本`,'↔')}${stat('样本成交量',compact(volume),'手',`${volumeRows.length} 个品种 · 仅全合约来源`,'▥')}${stat('持仓量变化',`<span class="${color(oiChange)}">${oiChange>0?'+':''}${compact(oiChange)}</span>`,'手',`${oiRows.length} 个品种 · 仅全合约来源`,'⇄')}</div>`+
 `<div class="section-header"><h2 class="section-title">重点品种<span class="section-sub">合约选择规则见各品种来源</span></h2><a class="text-link" href="#trends">查看全部品种 ↗</a></div><div class="mini-cards">${['au','cu','rb','sc','m','ta','lc','si'].map(code=>ms.find(m=>m.code===code)).filter(Boolean).map(m=>`<button class="mini ${state.selected===m.code?'selected':''}" data-select="${m.code}"><div class="mini-head"><span class="mini-title">${m.name}</span><span class="mini-code">${m.main.contract.toUpperCase()} · ${m.exchange}</span></div><div class="mini-value">${num(m.main.close,decimals(m))}</div>${spark(m,'spark')}<div class="mini-foot"><span class="${color(m.main.changePct)}">${signed(m.main.changePct,2)}%</span><small>${m.unit}</small></div></button>`).join('')}</div>`+
 `<div class="main-grid" id="detail">${chartPanel()}${rankPanel()}</div>`+
 `<div class="section-header"><h2 class="section-title">商品全景<span class="section-sub">价格、趋势与持仓变化</span></h2><span class="text-link">${DATA.asOf}</span></div>${tableShell()}<div class="info-strip">覆盖 ${exLabel()} 的已取得样本。代表合约为当日有成交且持仓量最大的合约；价格图固定跟踪该合约，不拼接主力连续价格。更多口径见 <a href="#sources">数据与方法 ↗</a></div>`;
}
function chartPanel(){const m=selected();return `<section class="panel"><div class="panel-top"><div><div class="panel-title">价格趋势</div><div class="panel-kicker">PRICE STRUCTURE / ${isFixed(m)?'固定合约':'连续行情'}</div></div>${marketSelect()}</div><div class="chart-meta"><span class="chart-value">${num(m.main.close,decimals(m))}</span><span class="${color(m.main.changePct)}">${signed(m.main.changePct,2)}%</span><span class="chart-unit">${m.unit}</span><span class="chart-unit">${m.aggregateScope==='representative-contract'?(m.mainMatchedContinuous?'已匹配主力合约':'盘后代表合约'):'持仓量最大合约'}</span></div><div class="chart-periods">${[20,40,70].map(n=>`<button class="chip ${state.period===n?'active':''}" data-period="${n}">${n===70?'全部':n+'日'}</button>`).join('')}</div><div class="chart" id="price-chart"></div><div class="chart-note"><span class="legend"><i></i>收盘价</span><span class="legend"><i class="ma5"></i>MA5</span><span class="legend"><i class="ma20"></i>MA20</span><br>${m.main.contract.toUpperCase()} · ${isFixed(m)?'固定合约':'连续行情（不可视为固定合约）'} · ${validHistory(m).length} 个样本<br>来源：<a href="${esc(sourceOf(m).url)}" target="_blank" rel="noopener">${esc(sourceOf(m).name)} ↗</a></div></section>`}
function rankPanel(){return `<section class="panel"><div class="panel-top"><div><div class="panel-title">增减仓观察</div><div class="panel-kicker">OPEN INTEREST / 全合约合计</div></div><div class="tabs"><button class="chip ${state.rankMode==='increase'?'active':''}" data-rank="increase">增仓</button><button class="chip ${state.rankMode==='decrease'?'active':''}" data-rank="decrease">减仓</button></div></div><div class="ranking" id="ranking"></div><div class="chart-note">单位：手。仅全合约合计参与排行，代表合约样本不混入；<br>增加与减少均不等同于方向性资金流入或流出。</div></section>`}
function ranking(){const a=[...DATA.markets].filter(m=>m.aggregateScope==='all-contracts').filter(m=>state.rankMode==='increase'?m.totalOiChange>0:m.totalOiChange<0).sort((a,b)=>state.rankMode==='increase'?b.totalOiChange-a.totalOiChange:a.totalOiChange-b.totalOiChange).slice(0,6);const max=Math.max(...a.map(m=>Math.abs(m.totalOiChange)),1);$('#ranking').innerHTML=a.length?a.map((m,i)=>`<button class="rank-row" data-select="${m.code}"><span class="rank-number">0${i+1}</span><span class="rank-name">${m.name}</span><span class="rank-track"><span style="width:${Math.abs(m.totalOiChange)/max*100}%;background:${m.totalOiChange>0?'#c78b77':'#8ea68b'}"></span></span><span class="rank-val ${color(m.totalOiChange)}">${m.totalOiChange>0?'+':''}${compact(m.totalOiChange)}</span></button>`).join(''):'<p class="empty">本次样本暂无该方向持仓变化。</p>';bindSelection($('#ranking'))}
function tableShell(){return `<div class="table-toolbar"><div class="filters">${['全部',...new Set(DATA.markets.map(m=>m.sector)),'自选'].map(s=>`<button class="filter-btn ${state.sector===s?'active':''}" data-sector="${s}">${s}</button>`).join('')}</div><select id="exchange-filter" class="select" aria-label="筛选交易所"><option value="全部">全部交易所</option>${DATA.coverage.exchanges.map(ex=>`<option value="${ex}" ${state.exchange===ex?'selected':''}>${exchangeNames[ex]||ex}</option>`).join('')}</select><label class="search"><span>⌕</span><input id="search" type="search" placeholder="搜索品种 / 合约" value="${esc(state.search)}" aria-label="搜索品种或合约"></label></div><div class="panel"><div class="table-wrap"><table class="market-table"><thead><tr><th>品种 / 合约</th><th>板块</th><th>收盘价</th><th><button data-sort="changePct">日涨跌幅 ↕</button></th><th>近 24 样本</th><th><button data-sort="volume">成交量 / 手 ↕</button></th><th><button data-sort="oiChange">品种增减仓 / 手 ↕</button></th><th>趋势状态</th><th>持仓排名</th></tr></thead><tbody id="market-body"></tbody></table></div><div class="table-bottom"><span id="table-count"></span><span>红涨绿跌 · 点击品种查看价格与席位结构</span></div></div>`}
function table(){let a=DATA.markets.filter(m=>(state.exchange==='全部'||m.exchange===state.exchange)&&(state.sector==='全部'||(state.sector==='自选'?state.favorites.includes(m.code):m.sector===state.sector))&&(`${m.name} ${m.code} ${m.main.contract}`.toLowerCase().includes(state.search.toLowerCase())));a.sort((a,b)=>{const value=m=>state.sort==='oiChange'?m.totalOiChange:state.sort==='volume'?m.totalVolume:m.main.changePct;const x=value(a),y=value(b);return x==null?(y==null?0:1):y==null?-1:(x-y)*state.order});$('#market-body').innerHTML=a.length?a.map(m=>{const t=trend(m);return `<tr class="${m.code===state.selected?'chosen':''}" data-row="${m.code}" tabindex="0" aria-label="查看${m.name}详情"><td><button class="star ${state.favorites.includes(m.code)?'saved':''}" data-star="${m.code}" aria-label="${state.favorites.includes(m.code)?'移除':'添加'}自选${m.name}">${state.favorites.includes(m.code)?'★':'☆'}</button><span class="market-name">${m.name}<small style="margin-left:25px">${m.main.contract.toUpperCase()} · ${m.exchange}</small></span></td><td><span class="badge">${m.sector}</span></td><td>${num(m.main.close,decimals(m))}</td><td class="${color(m.main.changePct)}">${signed(m.main.changePct,2)}%</td><td>${spark(m)}</td><td>${num(m.totalVolume)}<small class="metric-note">${coverageText(m)}</small></td><td class="${color(m.totalOiChange)}">${signed(m.totalOiChange)}</td><td><span class="badge ${t.class}">${t.name}</span></td><td>${m.ranks.length?'<button class="chip text-link" data-position="'+m.code+'">查看 ↗</button>':'<span class="neutral">未取得</span>'}</td></tr>`}).join(''):'<tr><td colspan="9" class="empty">没有匹配品种。试试其他关键词，或点击星标添加自选。</td></tr>';$('#table-count').textContent=`显示 ${a.length} / ${DATA.markets.length} 个品种 · 数据日期 ${DATA.asOf}`;
 $$('[data-row]').forEach(el=>{const action=()=>{state.selected=el.dataset.row;if(state.view==='trends'){location.hash='positions'}else{render();$('#detail')?.scrollIntoView({behavior:'smooth',block:'center'})}};el.onclick=e=>{if(!e.target.closest('[data-star],[data-position]'))action()};el.onkeydown=e=>{if(e.target!==el)return;if(e.key==='Enter'||e.key===' '){e.preventDefault();action()}}});
 $$('[data-position]').forEach(b=>b.onclick=e=>{e.stopPropagation();state.selected=b.dataset.position;location.hash='positions'});
 $$('[data-star]').forEach(b=>b.onclick=e=>{e.stopPropagation();const c=b.dataset.star;state.favorites=state.favorites.includes(c)?state.favorites.filter(x=>x!==c):[...state.favorites,c];try{localStorage.setItem('guanlan-favorites',JSON.stringify(state.favorites))}catch{}table()})}
function trends(){const ms=DATA.markets;const bull=ms.filter(m=>trend(m).id==='bull').length,bear=ms.filter(m=>trend(m).id==='bear').length,mixed=ms.filter(m=>trend(m).id==='mixed').length;return heading('趋势，放在全景里看。','统一比较各商品代表合约的 MA5、MA20 与收盘价位置。','TREND MONITOR / 趋势全景')+`<div class="stats-grid">${stat('趋势偏多',bull,'个','收盘价 > MA20 且 MA5 > MA20')}${stat('趋势偏空',bear,'个','收盘价 < MA20 且 MA5 < MA20','↘')}${stat('方向分化',mixed,'个','价格与均线方向未同时确认','⇄')}${stat('历史窗口',DATA.coverage.tradingDays,'个交易日',`${DATA.coverage.firstDate} 起可用文件`,'◷')}</div><div class="coverage">这里的趋势标签是本站透明规则的计算结果：使用当前代表合约的历史收盘价，短周期 MA5、中周期 MA20。它并非实际 CTA 基金仓位，也不是参考站的专有模型。</div>${tableShell()}`}
function positions(){const m=selected(),r=m.ranks;const long=r.length?r.reduce((s,r)=>s+(r.long||0),0):null,short=r.length?r.reduce((s,r)=>s+(r.short||0),0):null;
 const ranked=(side)=>`<section class="panel"><div class="panel-top"><div><div class="panel-title">${side==='long'?'持买单量排名':'持卖单量排名'}</div><div class="panel-kicker">${side==='long'?'LONG POSITIONS':'SHORT POSITIONS'} / ${r.length?'已公布 '+r.length+' 名':'暂无排名'}</div></div><span class="badge">${m.main.contract.toUpperCase()}</span></div><div class="table-wrap"><table class="market-table position-table"><thead><tr><th>排名 / 会员简称</th><th style="text-align:right">持仓量 / 手</th><th>日增减 / 手</th></tr></thead><tbody>${r.length?r.map(v=>`<tr><td><span style="color:#b2baa4;margin-right:13px">${String(v.rank).padStart(2,'0')}</span>${esc(v[side+'Name'])}</td><td style="text-align:right">${num(v[side])}</td><td class="${color(v[side+'Change'])}">${signed(v[side+'Change'])}</td></tr>`).join(''):'<tr><td colspan="3" class="empty">该合约未取得公开持仓排名。<br>不会以零持仓代替缺失数据。</td></tr>'}</tbody></table></div></section>`;
 return heading('席位背后，是持仓结构。','按合约阅读交易所公布的会员排名，分别观察多空两侧。','POSITIONING / 持仓结构')+`<div class="position-banner"><h2 class="section-title">${m.name} <span class="section-sub">${m.main.contract.toUpperCase()} · ${m.exchange} · ${m.main.date}</span></h2>${marketSelect()}</div><div class="position-metrics">${stat('排名样本多头持仓',long===null?'—':compact(long),'手',`独立买单排名 · ${r.length} 名`,'↗')}${stat('排名样本空头持仓',short===null?'—':compact(short),'手',`独立卖单排名 · ${r.length} 名`,'↘')}${stat('两侧样本持仓差',long===null?'—':`<span class="${color(long-short)}">${signed(long-short)}</span>`,'手','多头排名合计 − 空头排名合计','⇄')}</div><div class="coverage">买单与卖单是两份独立排名，同一行不代表同一家会员。排名只覆盖交易所公布的会员样本，不代表机构自营仓位，也不是全市场净多空；全市场多空持仓相互对应。</div><div class="position-columns">${ranked('long')}${ranked('short')}</div><div class="info-strip">来源：${m.rankSource?.url?`<a href="${esc(m.rankSource.url)}" target="_blank" rel="noopener">${esc(m.rankSource.name||'持仓排名原始文件')} ↗</a>`:'未取得该合约的可核实排名来源'} · 日期 ${DATA.asOf}。${esc(m.rankingNote||'')} ${esc(m.rankingFallbackNote||'')}</div>`}
function sources(){
 const rows=DATA.exchangeSources||[], markets=DATA.markets;
 const sourceCards=rows.map(x=>{const a=markets.filter(m=>m.exchange===x.exchange);const official=a.length&&a.every(m=>sourceOf(m).official===true);const counts=a.map(m=>validHistory(m).length);return `<article class="method-card"><div class="eyebrow">${x.exchange} / ${official?'OFFICIAL DATA':'PUBLIC DATA'}</div><h2>${exchangeNames[x.exchange]||x.exchange}</h2><div class="source-status ${a.length?'':'wait'}">${a.length?'已接入 '+a.length+' 个品种':'尚未取得可用数据'} · ${official?'官方公开文件':'来源见下方链接'}</div><p>行情：${esc(x.quoteStatus||'未取得')}<br>排名：${a.filter(m=>m.ranks.length).length} / ${a.length} 个代表合约<br>报告日期：${esc(x.date||DATA.asOf)}<br>历史样本：${counts.length?Math.min(...counts)+'–'+Math.max(...counts):'—'} 个交易日</p><p>${x.quoteUrl||x.url?`<a href="${esc(x.quoteUrl||x.url)}" target="_blank" rel="noopener">行情来源 ↗</a>`:''}${x.rankUrl?` &nbsp; <a href="${esc(x.rankUrl)}" target="_blank" rel="noopener">${a.some(m=>m.ranks.length)?'持仓排名来源':'排名入口（本次未取得）'} ↗</a>`:''}</p>${x.note?`<div class="source-box">${esc(x.note)}</div>`:''}${x.rankingSourceNote?`<div class="source-box">${esc(x.rankingSourceNote)}</div>`:''}</article>`}).join('');
 return heading('每个数字，都有出处。','逐交易所核实来源、日期和数据缺口。','DATA & METHODOLOGY / 数据与方法')+`<div class="coverage">当前为 ${DATA.asOf} 的盘后数据快照，已取得 ${markets.length} 个品种。覆盖 ${exLabel()}。各交易所及品种的历史长度、排名可用性不同，请以下方明细为准。</div><div class="source-grid">${sourceCards}</div><article class="method-card"><h2>各品种数据明细</h2><div class="table-wrap"><table class="market-table"><thead><tr><th>品种 / 交易所</th><th>代表合约</th><th>历史样本</th><th>合计口径</th><th>行情来源</th><th>排名</th></tr></thead><tbody>${markets.map(m=>`<tr><td>${esc(m.name)} · ${m.exchange}</td><td>${m.main.contract.toUpperCase()}</td><td>${validHistory(m).length} 日 / ${isFixed(m)?'固定合约':'连续行情'}</td><td>${coverageText(m)}</td><td><a href="${esc(sourceOf(m).url)}" target="_blank" rel="noopener">${esc(sourceOf(m).name)} ↗</a></td><td>${m.ranks.length?m.ranks.length+' 名':'未取得'}<small class="metric-note">${m.rankSource?.provider==='eastmoney'?'东方财富（备用）':m.ranks.length?'官方来源':''}</small></td></tr>`).join('')}</tbody></table></div></article><article class="method-card"><h2>计算方法与数据边界</h2><h3>合约与价格</h3><p>官方全合约数据可用时，在当日有成交、收盘价有效的合约中选持仓量最大者作为代表合约。固定合约历史始终跟踪同一个交割月份；若只能取得连续行情，会另行标注，不计算固定合约趋势。未取得价格或增减仓显示“—”，不会以零补造。</p><h3>涨跌基准</h3><p>有昨结算价时使用（收盘价 ÷ 昨结算价 − 1）×100%。无可核实的昨结算价时不填该涨跌幅，不使用日线昨收默替。价格单位在品种图表旁展示，成交和持仓单位为手。</p><h3>趋势标签</h3><p>使用同一固定合约最近 5 / 20 个有效收盘样本的简单平均。收盘与 MA5 同高于 MA20 为偏多，同低于为偏空，否则分化。不足 20 个样本不生成趋势标签；缺失日期不插值。它不代表基金真实 CTA 仓位。</p><h3>持仓与样本合计</h3><p>增减仓以手数展示，不等同于资金净流量。全合约合计和代表合约样本分开标注；成交量与增减仓汇总卡、增减仓排行仅统计全合约来源，代表合约样本不混入。表格与导出逐项标明口径。买单与卖单是独立排名，同一行未必是同一家会员；两侧样本之差不等同于全市场净多空，也不代表会员自营头寸。</p><h3>更新与快照</h3><p>${$('#embedded-data')?'这是内嵌数据的离线快照，文件不会自动联网更新。':'在线版在北京时间工作日 18:17 和 20:17 检查盘后数据。重新载入可读取最近成功发布的快照；来源校验未通过时保留上一份数据。GitHub 调度可能延迟。'} 快照整理时间：${new Date(DATA.fetchedAt).toLocaleString('zh-CN',{timeZone:'Asia/Shanghai',hour12:false})} 北京时间。官方缺文件或请求失败的日期均不使用示例数补齐。</p><h3>彭博 / 万得</h3><p>当前使用已注明出处的公开数据，未连接 Bloomberg 或 Wind 付费终端，也不将公开新闻页冒称终端数据库。</p></article>`;
}
function chart(){const box=$('#price-chart');if(!box)return;const m=selected(),all=validHistory(m),subset=all.slice(-state.period);if(!subset.length){box.innerHTML='<p class="empty">暂无历史价格</p>';return}const W=700,H=238,p={l:15,r:72,t:17,b:30};const points=subset.map((v,i)=>{const idx=all.indexOf(v);return {...v,ma5:priceMeanAt(m,v.date,5),ma20:priceMeanAt(m,v.date,20)}});const vals=points.flatMap(v=>[v.close,v.ma5,v.ma20]).filter(v=>v!==null);let lo=Math.min(...vals),hi=Math.max(...vals);const margin=(hi-lo)*.15||hi*.01||1;lo-=margin;hi+=margin;const x=i=>p.l+(W-p.l-p.r)*i/Math.max(1,points.length-1),y=v=>p.t+(H-p.b-p.t)*(hi-v)/(hi-lo);const path=key=>points.map((v,i)=>v[key]!==null?`${i===0||points[i-1][key]===null?'M':'L'}${x(i).toFixed(2)},${y(v[key]).toFixed(2)}`:'').join(' ');const base=H-p.b;const grid=Array.from({length:5},(_,i)=>{const v=lo+(hi-lo)*i/4;return `<line x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}" stroke="#edf0e7" stroke-dasharray="3 4"/><text x="${W-p.r+12}" y="${y(v)+3}" fill="#9ca68f" font-size="10">${num(v,m.code==='au'?1:0)}</text>`}).join('');const labels=[0,Math.floor((points.length-1)/2),points.length-1].map(i=>`<text x="${x(i)}" y="${H-7}" text-anchor="${i===0?'start':i===points.length-1?'end':'middle'}" fill="#9ca68f" font-size="10">${points[i].date.slice(5)}</text>`).join('');box.innerHTML=`<svg viewBox="0 0 ${W} ${H}" role="img" aria-label="${m.name}${m.main.contract}固定合约收盘价和均线走势图"><defs><linearGradient id="area" x1="0" y1="0" x2="0" y2="1"><stop offset="0%" stop-color="#79946d" stop-opacity=".17"/><stop offset="100%" stop-color="#79946d" stop-opacity="0"/></linearGradient></defs>${grid}<path d="${path('close')} L${x(points.length-1)},${base} L${x(0)},${base} Z" fill="url(#area)"/><path d="${path('ma20')}" fill="none" stroke="#9dabb3" stroke-width="1.2" stroke-dasharray="4 3"/><path d="${path('ma5')}" fill="none" stroke="#ba9860" stroke-width="1.2"/><path d="${path('close')}" fill="none" stroke="#658463" stroke-width="2"/><circle cx="${x(points.length-1)}" cy="${y(points.at(-1).close)}" r="3" fill="#658463"/>${labels}<line id="crosshair" x1="0" x2="0" y1="${p.t}" y2="${base}" stroke="#b8c4ae" stroke-dasharray="3 3" opacity="0"/></svg><div class="chart-tooltip"></div>`;const svg=box.querySelector('svg'),tip=box.querySelector('.chart-tooltip'),cross=box.querySelector('#crosshair');svg.onpointermove=e=>{const rect=svg.getBoundingClientRect(),pos=(e.clientX-rect.left)/rect.width*W,i=Math.max(0,Math.min(points.length-1,Math.round((pos-p.l)/(W-p.r-p.l)*(points.length-1)))),v=points[i];cross.setAttribute('x1',x(i));cross.setAttribute('x2',x(i));cross.setAttribute('opacity','1');tip.style.display='block';tip.style.top='18px';tip.style.left=Math.min(Math.max(10,e.clientX-rect.left-30),rect.width-158)+'px';tip.innerHTML=`${v.date}<br>收盘 ${num(v.close,2)} ${m.unit}<br>MA5 ${num(v.ma5,2)} · MA20 ${num(v.ma20,2)}`};svg.onpointerleave=()=>{cross.setAttribute('opacity','0');tip.style.display='none'}}
function bindSelection(root=document){root.querySelectorAll('[data-select]').forEach(b=>b.onclick=()=>{state.selected=b.dataset.select;render();$('#detail')?.scrollIntoView({behavior:'smooth',block:'center'})})}
function exportCsv(){const header=['数据日期','品种','交易所','代表合约','计价单位','收盘价','结算价','昨结算价','涨跌幅%','品种成交量_手','品种持仓量_手','品种持仓变化_手','趋势标签','日行情来源','合计口径','合约选择规则','合计口径','合约选择规则','合计口径','合约选择规则','合计口径','合约选择规则'];const lines=DATA.markets.map(m=>[m.main.date,m.name,m.exchange,m.main.contract,m.unit,m.main.close,m.main.settle,m.main.prevSettle,m.main.changePct,m.totalVolume,m.totalOi,m.totalOiChange,trend(m).name,sourceOf(m).url,coverageText(m),m.mainSelection||'持仓量最大合约']);const csv='\ufeff'+[header,...lines].map(row=>row.map(v=>'"'+String(v??'').replaceAll('"','""')+'"').join(',')).join('\r\n');const url=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'})),a=document.createElement('a');a.href=url;a.download=`商品研究终端_境内商品_${DATA.asOf}.csv`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast('已导出当前快照及来源链接')}
function toast(msg){$('#toast').textContent=msg;$('#toast').classList.add('show');setTimeout(()=>$('#toast').classList.remove('show'),2200)}
// BEGIN RESEARCH UI
function factorPct(v,d=2){return v==null?'—':signed(v,d)+'%'}
function priceMeanAt(m,date,n){const cal=DATA.research?.calendar;if(!cal){const all=validHistory(m),i=all.findIndex(h=>h.date===date);return i>=n-1?mean(all.slice(i-n+1,i+1).map(h=>h.close)):null}const i=cal.indexOf(date);if(i<n-1)return null;const days=cal.slice(i-n+1,i+1),map=new Map(validHistory(m).map(h=>[h.date,h.close]));return days.every(d=>map.has(d))?mean(days.map(d=>map.get(d))):null}
function factorNum(v,d=2,suffix=''){return v==null?'—':num(v,d)+suffix}
function researchStatusLabel(a){return a.status==='多维同向'&&a.trendDirection===1?'盘面一致偏多':a.status==='多维同向'&&a.trendDirection===-1?'盘面一致偏空':a.status}
function researchBadge(a){const label=researchStatusLabel(a);return `<span title="${a.asOf} 连续均线与真实合约价仓、席位的规则状态；不包含基本面投票" class="badge ${a.status==='多维同向'?'positive':a.status==='存在分歧'?'negative':''}">${a.status==='多维同向'?'':'历史'}${label}</span>`}
function researchMetric(label,value,note){return `<div class="factor-metric"><div>${label}</div><strong>${value}</strong><small>${note}</small></div>`}

function deviationObservation(a){return a.deviationWatch||a.deviationEpisode}
const deviationState={filter:'全部',expanded:false};
function deviationCell(a){
 const d=deviationObservation(a);
 return `<span class="deviation-number ${d?'deviation-emphasis':''}">${factorPct(a.deviation20,1)}</span><small class="metric-note">${factorNum(a.distanceAtr20,2,' ATR')}${d?' · '+d.label:''}</small>`;
}
function deviationPanel(){
 const ms=DATA.markets.filter(m=>deviationObservation(m.analysis)),valid=DATA.markets.filter(m=>Number.isFinite(m.analysis.distanceAtr20)).length;
 return `<section class="panel deviation-panel" id="deviation-watch" aria-label="均值偏离观察"><div class="panel-top"><div><div class="eyebrow">MEAN DEVIATION / ${DATA.asOf} 收盘</div><h2 class="panel-title">均值偏离观察 <span class="deviation-total">${ms.length} 个</span></h2><div class="panel-kicker">上方关注回调风险 · 下方关注反弹可能 · 与趋势同向状态分别观察</div></div><a class="text-link" href="#research-method" id="deviation-method">筛选口径 ↗</a></div><div class="deviation-toolbar"><div class="filters">${['全部','上方偏离','下方偏离','修复跟踪','已有反向收盘'].map(f=>`<button class="filter-btn ${deviationState.filter===f?'active':''}" data-deviation-filter="${f}" aria-pressed="${deviationState.filter===f}">${f}</button>`).join('')}</div><span>${valid} / ${DATA.markets.length} 个可计算</span></div><div id="deviation-results" aria-live="polite"></div><div class="deviation-foot">触发：|收盘 − MA20| / ATR14 ≥ 2；退出阈值后保留5个交易日修复跟踪。统一阈值未分品种校准，未验证反转胜率。仅使用标注日期的收盘数据，非实时预警。</div></section>`;
}
function deviationRows(){
 const ms=DATA.markets.filter(m=>{const d=deviationObservation(m.analysis);return d&&(deviationState.filter==='全部'||deviationState.filter===d.label||deviationState.filter==='上方偏离'&&d.side==='above'||deviationState.filter==='下方偏离'&&d.side==='below'||deviationState.filter==='修复跟踪'&&m.analysis.deviationEpisode?.sessionsAfterHit>0||deviationState.filter==='已有反向收盘'&&d.retracing)}).sort((a,b)=>Math.abs(b.analysis.distanceAtr20)-Math.abs(a.analysis.distanceAtr20)||a.code.localeCompare(b.code));
 const shown=deviationState.expanded?ms:ms.slice(0,6);
 $('#deviation-results').innerHTML=shown.length?`<div class="deviation-list">${shown.map(m=>{const a=m.analysis,d=deviationObservation(a);return `<button class="deviation-row" data-deviation-code="${m.code}" aria-label="查看${esc(m.name)}偏离证据"><span class="deviation-instrument"><strong>${esc(m.name)}</strong><small>${m.main.contract.toUpperCase()} · ${m.exchange}</small></span><span class="deviation-distance"><b>${factorNum(a.distanceAtr20,2,' ATR')}</b><small>${d.label} · ${factorPct(a.deviation20,1)}</small></span><span class="deviation-context"><strong>${d.focus}${m.analysis.deviationEpisode?' · '+m.analysis.deviationEpisode.phase:''}</strong><small>${a.trendLabel} · ${d.priceCue}${d.rangeReentry?' · 盘中越界后收回':''}</small></span><span class="deviation-arrow" aria-hidden="true">↗</span></button>`}).join('')}</div><div class="deviation-list-bottom"><span>当前条件 ${ms.length} 个 · 已显示 ${shown.length} 个</span>${ms.length>6?`<button class="text-link" id="deviation-expand" aria-expanded="${deviationState.expanded}">${deviationState.expanded?'收起列表':'展开全部 '+ms.length+' 个'} ${deviationState.expanded?'↑':'↓'}</button>`:''}</div>`:'<div class="empty">当前条件下没有品种；这不代表没有市场风险。</div>';
 $$('[data-deviation-code]').forEach(b=>b.onclick=()=>selectResearch(b.dataset.deviationCode));
 if($('#deviation-expand'))$('#deviation-expand').onclick=()=>{deviationState.expanded=!deviationState.expanded;deviationRows()};
}
function bindDeviation(){
 deviationRows();
 $$('[data-deviation-filter]').forEach(b=>b.onclick=()=>{deviationState.filter=b.dataset.deviationFilter;deviationState.expanded=false;$$('[data-deviation-filter]').forEach(el=>{el.classList.toggle('active',el.dataset.deviationFilter===deviationState.filter);el.setAttribute('aria-pressed',String(el.dataset.deviationFilter===deviationState.filter))});deviationRows()});
 $('#deviation-method').onclick=e=>{e.preventDefault();const methods=$('#research-method'),fold=methods.closest('details');if(fold)fold.open=true;methods.scrollIntoView({behavior:'smooth',block:'start'})};
}
function deviationEpisodeDetail(a){
 const e=a.deviationEpisode;if(!e)return '';
 return `<p class="episode-summary"><strong>${esc(e.phase)}</strong> · 样本内首次触发 ${esc(e.firstAt)}；最远 ${esc(e.peakAt)} ${factorNum(e.peakDistance,2,' ATR')}；当前 ${factorNum(e.latestDistance,2,' ATR')}。价均差较最远ATR时点收敛 ${factorNum(e.gapContractionPct,1,'%')}。${e.sessionsAfterHit?'距最近阈值触发 '+e.sessionsAfterHit+' 个交易日。':''}收敛包含均线移动影响，不是价格收益率。</p>`;
}
function deviationDetail(a){
 const d=deviationObservation(a);
 if(!d)return `<div class="deviation-detail quiet"><strong>均值偏离观察</strong><p>${a.distanceAtr20==null?'价格或ATR样本不足，无法判定是否进入观察范围。':'当前未达到2 ATR观察门槛；不代表没有回调或反弹风险。'}</p></div>`;
 return `<div class="deviation-detail"><div><strong>${d.label} · ${d.focus}</strong><b>${factorNum(a.distanceAtr20,2,' ATR')}</b></div><p>收盘偏离 MA20 ${factorPct(a.deviation20)}。${d.observations.length?d.observations.map(esc).join('；')+'。':'当日尚未出现向均值方向的反向收盘。'}${d.caveat}</p>${deviationEpisodeDetail(a)}<small>趋势方向与偏离程度可以同时存在；地缘、天气、政策和供需冲击尚未接入，不能据此排除趋势延续。</small></div>`;
}

function research(){
 const r=DATA.research,ms=DATA.markets;if(!r)return heading('研究数据尚未生成','请先运行分析脚本，再导出 HTML。','RESEARCH / 研究雷达');
 const positive=ms.filter(m=>m.analysis.return20>0).length,breaks=ms.filter(m=>m.analysis.breakout).length;
 return heading('把变化，变成可核查的线索。','趋势 × 参与度 × 席位样本。先看证据之间是否一致，再看还缺少什么。','RESEARCH RADAR / 加工后的市场证据')+
 `<div class="research-brief"><div class="eyebrow">${DATA.asOf} / EVIDENCE BRIEF</div><h2>${r.aligned} 个品种盘面指标同向，${r.conflicts} 个存在分歧。</h2><p>20 交易日收益为正 ${positive} / ${ms.filter(m=>Number.isFinite(m.analysis.return20)).length} 个，${breaks} 个收盘越过前 20 日高低点。价格指标基于比例后复权连续序列，量仓与席位保留真实合约；“同向”仅为盘面规则一致，包含重复的价格信息；未验证未来收益，基本面另行核对；下方偏离观察独立提示价格远离均值的情况。</p><a href="#research-method" id="jump-research-method" class="text-link">查看口径与阈值 ↓</a></div>`+
 `<div class="stats-grid">${stat('20 日正收益广度',`${positive}<span class="stat-divider"> / ${ms.filter(m=>Number.isFinite(m.analysis.return20)).length}</span>`,'个','比例后复权连续收益 · 固定基准','↗')}${stat('盘面指标同向',r.aligned,'个','连续均线与真实合约价仓/席位同向；非独立证据','⊞')}${stat('需要复核的分歧',r.conflicts,'个','趋势反向或席位存量与增减项反向','⇄')}${stat('量能放大',ms.filter(m=>m.analysis.volumeRatio20>=1.5).length,'个','成交量 ≥ 前 20 交易日均量的 1.5 倍','▥')}</div>`+
 deviationPanel()+`<div class="section-header"><h2 class="section-title">当日复核线索<span class="section-sub">按明确规则触发 · 可点开证据</span></h2><span class="text-link">不是交易指令</span></div>${researchAlerts()}<div class="research-grid"><section class="panel"><div class="panel-top"><div><div class="panel-title">价仓地图 · 同期五日变化</div><div class="panel-kicker">横轴看价格涨跌 · 纵轴看合约持仓增减</div></div><span class="badge">点击圆点查看</span></div><div id="research-scatter" class="research-scatter"></div><div class="chart-note">每个点使用同一个固定合约的五交易日端点。向上表示持仓增加，向右才表示价格上涨；缺少价格或持仓端点的品种不入图。持仓增减不能区分新增多头或空头。</div></section><section class="panel"><div class="panel-top"><div><div class="panel-title">板块强弱与广度</div><div class="panel-kicker">20 日收益中位数 / 正收益品种占比</div></div></div><div class="sector-tiles">${r.sectors.map(s=>`<button data-research-sector="${esc(s.sector)}" class="sector-tile ${state.rSector===s.sector?'chosen':''}"><div><strong>${s.sector}</strong><span class="${color(s.medianReturn20)}">${factorPct(s.medianReturn20)}</span></div><small>${s.positive20} / ${s.return20Count} 个正收益 · 板块共 ${s.count} 个样本</small><div class="breadth"><span style="flex:${s.positive20||.001}"></span><span style="flex:${s.return20Count-s.positive20||.001}"></span></div></button>`).join('')}</div><div class="chart-note">等权品种样本的中位数，并非板块指数。点击板块筛选下表，再点一次取消。</div></section></div>`+
 `<div id="research-detail">${researchDetail()}</div><div class="section-header" id="research-table-title"><h2 class="section-title">横截面研究矩阵<span class="section-sub">点击列标题排序 · 点击品种展开解释</span></h2><span class="text-link" id="research-count"></span></div><div class="table-toolbar"><div class="filters">${['全部','盘面一致偏多','盘面一致偏空','存在分歧','大幅偏离','放量','突破','缺少席位'].map(v=>`<button data-research-filter="${v}" class="filter-btn ${state.rFilter===v?'active':''}">${v}</button>`).join('')}</div><label class="search">⌕<input id="research-search" type="search" aria-label="搜索研究品种" placeholder="搜索品种 / 合约" value="${esc(state.rSearch)}"></label></div><div class="panel"><div class="table-wrap"><table class="market-table research-table"><thead><tr><th>品种 / 合约</th><th><button data-factor-sort="return20">20 日收益 ↕</button></th><th><button data-factor-sort="strengthPercentile20">相对强度分位 ↕</button></th><th><button data-factor-sort="distanceAtr20">均值偏离 / ATR ↕</button></th><th>真实合约当日价仓</th><th><button data-factor-sort="oiReturn5">真实合约5日持仓 ↕</button></th><th><button data-factor-sort="volumeRatio20">20 日量比 ↕</button></th><th><button data-factor-sort="seatDifferencePctOi">席位样本差 / OI ↕</button></th><th><button data-factor-sort="volatility20">年化波动率 ↕</button></th><th>盘面证据状态</th></tr></thead><tbody id="research-body"></tbody></table></div><div class="table-bottom"><span id="research-filter-note"></span><span>收益：后复权连续；价仓及席位：真实合约。— 代表不可计算。</span></div></div>${researchMethods()}`;
}
function researchAlerts(){
 const ms=DATA.markets,abs=v=>Math.abs(v??0);
 const conflict=ms.filter(m=>m.analysis.seatTrendConflict).sort((a,b)=>abs(b.analysis.return20)-abs(a.analysis.return20))[0];
 const volume=ms.filter(m=>m.analysis.volumeRatio20>=1.5).sort((a,b)=>b.analysis.volumeRatio20-a.analysis.volumeRatio20)[0];
 const breakout=ms.filter(m=>m.analysis.breakout).sort((a,b)=>abs(b.analysis.return20)-abs(a.analysis.return20))[0];
 const cards=[['趋势 / 席位分歧',conflict,m=>`${m.analysis.trendLabel}，但买卖排名样本差${m.analysis.seatDifference>0?'为正':'为负'}。`,m=>`20 日 ${factorPct(m.analysis.return20)} · 样本差 ${signed(m.analysis.seatDifference)} 手`],['量能异常放大',volume,m=>`成交量达到前20日均量的 ${num(m.analysis.volumeRatio20,2)} 倍。`,m=>`${m.analysis.quadrant} · 同合约 ${signed(m.analysis.fixedOiChange)} 手`],['价格区间突破',breakout,m=>`${m.analysis.breakout}，需要结合增减仓核查。`,m=>`${m.analysis.quadrant} · 量比 ${factorNum(m.analysis.volumeRatio20,2,'×')}`]];
 return `<div class="alert-grid">${cards.map(([label,m,body,foot])=>m?`<button class="research-alert" data-research-select="${m.code}"><div class="eyebrow">${label}</div><div class="alert-title">${esc(m.name)} <span>${m.main.contract.toUpperCase()} ↗</span></div><p>${body(m)}</p><small>${foot(m)}</small></button>`:`<div class="research-alert"><div class="eyebrow">${label}</div><div class="alert-title">当前未触发</div><p>本次有效样本没有符合该规则的品种。</p></div>`).join('')}</div>`;
}
function researchDetail(){
 const m=selected(),a=m.analysis;
 const lines=(arr,empty)=>arr.length?`<ul>${arr.map(s=>`<li>${esc(s)}</li>`).join('')}</ul>`:`<p>${empty}</p>`;
 return `<section class="panel research-detail-panel"><div class="panel-top"><div><div class="panel-title">${m.name} · 证据拆解 ${researchBadge(a)}</div><div class="panel-kicker">${m.main.contract.toUpperCase()} / ${m.exchange} / ${a.asOf} · 可观察项 ${a.dimensionsAvailable}/3 · 同向的盘面观察 ${a.alignedDimensions}/3；非独立投票</div></div><select class="select" id="research-market-select" aria-label="选择证据拆解品种">${DATA.markets.map(n=>`<option value="${n.code}" ${m.code===n.code?'selected':''}>${n.name} · ${n.main.contract.toUpperCase()}</option>`).join('')}</select></div>${deviationDetail(a)}<div class="factor-grid">${researchMetric('5 / 20 日收益',`${factorPct(a.return5)} <span>/ ${factorPct(a.return20)}</span>`,'比例后复权连续价 · 同一复权口径')}${researchMetric('20 日相对强度',factorNum(a.strengthPercentile20,1,' 分位'),`${a.strengthPeerCount} 个有效品种横向比较`)}${researchMetric('量能 / 持仓',`${factorNum(a.volumeRatio20,2,'×')} <span>/ ${factorPct(a.oiReturn5)}</span>`,'前20日量比 / 同合约5日持仓变化')}${researchMetric('20 日年化波动',factorNum(a.volatility20,1,'%'),'20个对数收益的样本标准差 × √252')}${researchMetric('均线斜率 / 乖离',`${factorPct(a.ma20Slope5)} <span>/ ${factorPct(a.deviation20)}</span>`,'MA20较5日前变化 / 收盘偏离MA20')}${researchMetric('价格 / 常态波幅',`${factorNum(a.distanceAtr20,2,' ATR')}`,'收盘偏离MA20 ÷ 简单ATR14')}</div><div class="evidence-columns"><article><h3><span class="evidence-dot"></span>与均线同向的盘面观察</h3>${lines(a.evidence,'当前没有足以归入与均线同向的盘面观察。')}</article><article><h3><span class="evidence-dot conflict"></span>反向盘面证据与待确认项</h3>${lines(a.counterEvidence,'当前规则未发现明显反向观察；不代表不存在风险。')}</article><article><h3><span class="evidence-dot missing"></span>不能由这些数据得出的结论</h3>${lines(a.unknowns,'暂无')}</article></div><div class="seat-insight"><strong>席位样本的内部结构</strong><span>买单前 5 / 已公布买单样本：${factorNum(a.seatLongTop5Share,1,'%')}</span><span>卖单前 5 / 已公布卖单样本：${factorNum(a.seatShortTop5Share,1,'%')}</span><span>多空增减项之差：${signed(a.seatDeltaDifference)} 手</span></div>${a.seatDeltaDifference!==null?`<div class="contributors"><div>买单变动贡献（绝对值前三）：${a.longContributors.map(v=>`${esc(v.name)} ${signed(v.change)}手`).join('；')}</div><div>卖单变动贡献（绝对值前三）：${a.shortContributors.map(v=>`${esc(v.name)} ${signed(v.change)}手`).join('；')}</div><small>仅解释当日排名表中的增减项；会员集合会变化，不是连续资金流，也不表示自营头寸。</small></div>`:`<div class="contributors"><small>${esc(m.rankingNote||'本次未取得该合约公开会员排名，因此不生成席位结构。')} ${esc(m.rankingFallbackNote||'')}</small></div>`}<div class="analysis-source">依据：<a href="${esc(sourceOf(m).url)}" target="_blank" rel="noopener">${esc(sourceOf(m).name)} ↗</a>${m.ranks.length&&m.rankSource?.url?` · <a href="${esc(m.rankSource.url)}" target="_blank" rel="noopener">${esc(m.rankSource.name||'会员排名')} ↗</a>`:''} · 真实合约 ${m.main.contract.toUpperCase()}；价格研究为比例后复权连续 · ${a.historyCount??0} 个研究样本</div></section>`;
}
function researchTable(){
 const matches=m=>{const a=m.analysis,f=state.rFilter;return (!state.rSector||a.sector===state.rSector)&&(`${m.name} ${m.code} ${m.main.contract}`.toLowerCase().includes(state.rSearch.toLowerCase()))&&(f==='全部'||f==='大幅偏离'&&!!deviationObservation(a)||f==='放量'&&a.volumeRatio20>=1.5||f==='突破'&&!!a.breakout||f==='缺少席位'&&!m.ranks.length||f===researchStatusLabel(a))};
 let ms=DATA.markets.filter(matches);ms.sort((m,n)=>{const a=m.analysis[state.rSort],b=n.analysis[state.rSort];return a==null?(b==null?0:1):b==null?-1:(a-b)*state.rOrder});
 $('#research-body').innerHTML=ms.length?ms.map(m=>{const a=m.analysis;return `<tr data-research-row="${m.code}" tabindex="0" class="${state.selected===m.code?'chosen':''}" aria-label="拆解${m.name}证据"><td class="market-name">${m.name}<small>${m.main.contract.toUpperCase()} · ${m.exchange}</small></td><td class="${color(a.return20)}">${factorPct(a.return20)}</td><td><div class="percentile"><span style="width:${a.strengthPercentile20??0}%"></span><b>${factorNum(a.strengthPercentile20,1)}</b></div></td><td>${deviationCell(a)}</td><td>${a.quadrant}</td><td class="${color(a.oiReturn5)}">${factorPct(a.oiReturn5)}</td><td>${factorNum(a.volumeRatio20,2,'×')}</td><td class="${color(a.seatDifferencePctOi)}">${factorPct(a.seatDifferencePctOi,1)}</td><td>${factorNum(a.volatility20,1,'%')}</td><td>${researchBadge(a)}<small class="metric-note">${a.dimensionsAvailable}/3 项可观察</small></td></tr>`}).join(''):'<tr><td colspan="10" class="empty">当前条件下没有品种。切换筛选条件，或取消板块选择。</td></tr>';
 $('#research-count').textContent=`${ms.length} / ${DATA.markets.length} 个品种`;
 $('#research-filter-note').innerHTML=`${state.rSector?`板块：${esc(state.rSector)} <button class="chip" id="clear-research-sector">取消 ×</button>`:'全部板块'} · 20 日收益有效样本 ${DATA.research.strengthPeerCount} 个`;
 $$('[data-research-row]').forEach(el=>{el.onclick=()=>selectResearch(el.dataset.researchRow);el.onkeydown=e=>{if(e.key==='Enter'){e.preventDefault();selectResearch(el.dataset.researchRow)}}});
 if($('#clear-research-sector'))$('#clear-research-sector').onclick=()=>{state.rSector='';researchTable();$$('[data-research-sector]').forEach(b=>b.classList.remove('chosen'))};
}
function selectResearch(code){state.selected=code;$('#research-detail').innerHTML=researchDetail();bindResearchDetail();researchTable();scatter();$('#research-detail').scrollIntoView({behavior:'smooth',block:'start'})}
function bindResearchDetail(){if($('#research-market-select'))$('#research-market-select').onchange=e=>selectResearch(e.target.value)}

const scatterState={mode:'focus'};
function scatterAnalysis(m){return m.fixedAnalysis||m.analysis}
function scatterSectorColor(m,sectors,colors){const index=sectors.indexOf(m.sector);return index>=0?colors[index%colors.length]:'var(--muted)'}
function scatterTickStep(v){const power=10**Math.floor(Math.log10(Math.max(v,.01)));return [1,2,2.5,5,10].find(n=>n*power>=v)*power}
function scatterLayout(markets,mode){
 const valid=markets.filter(m=>Number.isFinite(scatterAnalysis(m).return5)&&Number.isFinite(scatterAnalysis(m).oiReturn5));
 const large=valid.filter(m=>Math.abs(scatterAnalysis(m).oiReturn5)>100).sort((a,b)=>Math.abs(scatterAnalysis(b).oiReturn5)-Math.abs(scatterAnalysis(a).oiReturn5));
 const shown=mode==='all'?valid:valid.filter(m=>Math.abs(scatterAnalysis(m).oiReturn5)<=100);
 const xMax=Math.max(2,...valid.map(m=>Math.abs(scatterAnalysis(m).return5)))*1.08,xStep=scatterTickStep(xMax/3),xLimit=Math.ceil(xMax/xStep)*xStep;
 const maxOi=Math.max(100,...valid.map(m=>scatterAnalysis(m).oiReturn5))*1.08,yStep=scatterTickStep(maxOi/4);
 const yMax=mode==='all'?Math.ceil(maxOi/yStep)*yStep:100;
 const yMin=mode==='all'?Math.min(-100,Math.floor(Math.min(0,...valid.map(m=>scatterAnalysis(m).oiReturn5))*1.08/100)*100):-100;
 const yTicks=mode==='all'?[yMin,0,...Array.from({length:Math.round(yMax/yStep)},(_,i)=>(i+1)*yStep)]:[-100,-50,0,50,100];
 return {valid,shown,large,xLimit,yMin,yMax,yTicks};
}
function scatterEndpoints(m){
 const a=scatterAnalysis(m),history=m.history.filter(h=>h.contract===m.main.contract);
 return {start:history.find(h=>h.date===a.return5Start),end:history.find(h=>h.date===a.asOf)};
}
function scatterDescription(m){
 const a=scatterAnalysis(m),e=scatterEndpoints(m);
 return `${m.name} · ${m.main.contract.toUpperCase()} | ${a.return5Start} → ${a.asOf} | 价格 ${factorPct(a.return5)} (${factorNum(e.start?.close)} → ${factorNum(e.end?.close)}) | 合约持仓 ${factorPct(a.oiReturn5)} (${factorNum(e.start?.oi,0)} → ${factorNum(e.end?.oi,0)} 手)`;
}
function scatter(){
 const box=$('#research-scatter');if(!box)return;
 const model=scatterLayout(DATA.markets,scatterState.mode),{valid,shown,large,xLimit,yMin,yMax,yTicks}=model;
 const W=720,H=390,p={l:75,r:25,t:40,b:65};
 const x=v=>p.l+(W-p.l-p.r)*(v/xLimit+1)/2,y=v=>p.t+(H-p.b-p.t)*(yMax-v)/(yMax-yMin);
 const sectors=DATA.research.sectors.map(s=>s.sector),colors=['#b77e3e','#4a86c5','#8b76ad','#6f8970','#9a7492','#5e9d9b','#a5a06a','#7e839e'];
 const gridX=[-1,-.5,0,.5,1].map(t=>{const v=t*xLimit;return `<line x1="${x(v)}" x2="${x(v)}" y1="${p.t}" y2="${H-p.b}" class="scatter-grid ${t===0?'zero':''}"/><text x="${x(v)}" y="${H-p.b+20}" text-anchor="middle" class="scatter-tick">${num(v,1)}%</text>`}).join('');
 const gridY=yTicks.map(v=>`<line x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}" class="scatter-grid ${v===0?'zero':''}"/><text x="${p.l-9}" y="${y(v)+4}" text-anchor="end" class="scatter-tick">${num(v,0)}%</text>`).join('');
 const largeTitle=scatterState.mode==='focus'?`超出主体区间 ${large.length} 个 · 下列品种未绘入当前图`:`大幅合约持仓变化 ${large.length} 个 · 已绘入全范围图`;
 box.innerHTML=`<div class="scatter-controls"><div class="filters"><button data-scatter-mode="focus" class="filter-btn ${scatterState.mode==='focus'?'active':''}" aria-pressed="${scatterState.mode==='focus'}">主体区间</button><button data-scatter-mode="all" class="filter-btn ${scatterState.mode==='all'?'active':''}" aria-pressed="${scatterState.mode==='all'}">全部范围</button></div><span>${DATA.asOf} 收盘 · 图内 ${shown.length} / ${valid.length} 个</span></div><div class="scatter-range-note">${scatterState.mode==='focus'?'纵轴显示 −100% 至 +100%；超出范围的品种保留在下方清单，可切换全部范围。':'纵轴使用实际全范围，保持线性比例；较大的持仓变化会压缩其他品种。'}</div><svg viewBox="0 0 ${W} ${H}" role="img" aria-label="五日价仓地图，横轴价格涨跌幅，纵轴合约持仓变化率，${scatterState.mode==='focus'?'主体区间':'全部范围'}，图内${shown.length}个品种"><rect x="${x(0)}" y="${p.t}" width="${W-p.r-x(0)}" height="${y(0)-p.t}" fill="var(--accent-bg)" opacity=".3"/><rect x="${p.l}" y="${y(0)}" width="${x(0)-p.l}" height="${H-p.b-y(0)}" fill="var(--accent-bg)" opacity=".3"/>${gridX}${gridY}<text x="${p.l}" y="17" class="scatter-axis">纵轴：5日合约持仓变化（%）</text><text x="${(W+p.l-p.r)/2}" y="${H-8}" text-anchor="middle" class="scatter-axis">横轴：5日价格涨跌幅（%）</text><text x="${p.l+8}" y="${p.t+16}" class="quadrant-label">价跌 · 仓增</text><text x="${W-p.r-8}" y="${p.t+16}" text-anchor="end" class="quadrant-label">价涨 · 仓增</text>${H-p.b-y(0)>30?`<text x="${p.l+8}" y="${H-p.b-8}" class="quadrant-label">价跌 · 仓减</text><text x="${W-p.r-8}" y="${H-p.b-8}" text-anchor="end" class="quadrant-label">价涨 · 仓减</text>`:''}${shown.map(m=>`<circle data-research-point="${m.code}" cx="${x(scatterAnalysis(m).return5)}" cy="${y(scatterAnalysis(m).oiReturn5)}" r="${state.selected===m.code?7:4.5}" fill="${scatterSectorColor(m,sectors,colors)}" fill-opacity=".8" stroke="${state.selected===m.code?'var(--accent)':'var(--surface)'}" stroke-width="${state.selected===m.code?2:1}" tabindex="0" role="button" aria-label="${esc(scatterDescription(m))}"><title>${esc(scatterDescription(m))}</title></circle>`).join('')}</svg><div class="scatter-legend">${sectors.map((s,i)=>`<span><i style="background:${colors[i%colors.length]}"></i>${s}</span>`).join('')}</div>${large.length?`<div class="scatter-extremes"><strong>${largeTitle}</strong>${large.map(m=>{const a=scatterAnalysis(m),e=scatterEndpoints(m);return `<button data-scatter-large="${m.code}" class="scatter-extreme"><span><b>${m.name}</b><small>${m.main.contract.toUpperCase()} · ${a.return5Start} → ${a.asOf}</small></span><span>价格 <b class="${color(a.return5)}">${factorPct(a.return5)}</b><small>${factorNum(e.start?.close)} → ${factorNum(e.end?.close)}</small></span><span>合约持仓 <b>${factorPct(a.oiReturn5)}</b><small>${factorNum(e.start?.oi,0)} → ${factorNum(e.end?.oi,0)} 手</small></span></button>`}).join('')}<p>变化率会被较低的起始持仓放大，也可能受移仓换月影响；不代表价格涨幅或品种整体资金流。点击核查固定合约证据。</p></div>`:''}<div class="chart-tooltip"></div>`;
 $$('[data-scatter-mode]').forEach(b=>b.onclick=()=>{scatterState.mode=b.dataset.scatterMode;scatter()});
 box.querySelectorAll('[data-scatter-large]').forEach(b=>b.onclick=()=>selectResearch(b.dataset.scatterLarge));
 box.querySelectorAll('[data-research-point]').forEach(c=>{const m=valid.find(m=>m.code===c.dataset.researchPoint);c.onclick=()=>selectResearch(m.code);c.onkeydown=e=>{if(e.key==='Enter'||e.key===' '){e.preventDefault();selectResearch(m.code)}};c.onpointermove=e=>{const rect=box.getBoundingClientRect(),tip=box.querySelector('.chart-tooltip'),a=scatterAnalysis(m),end=scatterEndpoints(m);tip.innerHTML=`<strong>${esc(m.name)} · ${m.main.contract.toUpperCase()}</strong><br>${a.return5Start} → ${a.asOf}<br>价格涨跌：${factorPct(a.return5)}<br>合约持仓：${factorPct(a.oiReturn5)}<br>持仓端点：${factorNum(end.start?.oi,0)} → ${factorNum(end.end?.oi,0)} 手`;tip.style.display='block';tip.style.left=Math.max(8,Math.min(e.clientX-rect.left+10,rect.width-240))+'px';tip.style.top=Math.max(5,e.clientY-rect.top-125)+'px'};c.onpointerleave=()=>box.querySelector('.chart-tooltip').style.display='none'});
}
function researchMethods(){return `<article class="method-card research-method" id="research-method"><h2>这些结论如何得出</h2><div class="method-columns"><div><h3>均值偏离观察</h3><p>距离＝（同口径后复权收盘价 − 当日MA20）÷ 简单ATR14。绝对值 ≥ 2 进入观察，按绝对距离排序；正值关注回调，负值关注反弹。退出阈值后保留5个交易日，缺失样本会中断事件；首次触发仅为当前样本内观察。价均差收敛同时受价格与均线变化影响，不是反弹收益。统一2 ATR仅为初始筛选门槛，不是历史极端分位，也不是标准差或反转概率。样本缺失或ATR为零时不入选；不依赖席位是否齐全。</p><p>“已有反向收盘”仅指上方偏离时收盘低于昨收，或下方偏离时高于昨收；“盘中越界后收回”指当日高/低越过此前20日边界，但收盘回到边界内。它们是当日价格事实，未确认趋势反转。偏离也可能通过横盘或均线移动收敛；均线不是公允价值。所有品种均适用筛选，未接入新闻与供需冲击。</p><h3>收益、强弱与风险</h3><p>5/20 日研究收益使用固定基准比例后复权连续价，换月按前日新旧合约收盘比率桥接；数据不足时留空。价仓与席位仍使用真实代表合约。横截面分位用 20 日收益的经验中位秩计算，同值同分位；只比较 ${DATA.research.strengthPeerCount} 个有效样本，不是全市场指数。</p><p>波动率用最近 20 个对数收益的样本标准差 × √252 年化，只描述历史波动。ATR14 为最近 14 个真实波幅的简单均值；真实波幅取当日高低差与相对昨收跳空的最大值。至少需要 15 个连续完整交易样本。</p></div><div><h3>量价持仓与突破</h3><p>量比＝当前具体合约成交量 ÷ 前 20 交易日平均成交量，排除当日。1.5 倍触发放量，0.7 倍以下标记缩量。收盘突破用前 20 日最高 / 最低成交价，排除当日。</p><p>价仓象限使用收盘到收盘收益和同一具体合约持仓变化；散点图两轴都用同一个 5 日区间。固定合约量仓也会受到移仓换月影响，不等同品种整体资金变化。增仓不能辨认新多或新空，减仓也不能单独证明空头回补或多头离场。</p></div><div><h3>三维同向与分歧</h3><p>三维同向必须同时满足：均线有方向；当日增仓且价格方向相同；买卖排名样本差与趋势方向相同，且席位存量差与当日增减项差没有反向。没有任何一维可以用缺失数据补齐。它只是规则共振，未做历史胜率、收益或因果验证。</p><p>“分歧”包括趋势与排名样本差反向、当日价格与均线反向、席位存量差与当日增减项差反向。缺少席位时仍可发现价格分歧，但不能形成完整三维同向。</p></div><div><h3>数据能解释到哪里</h3><p>买卖排名是不同会员集合；前 5 占比的分母是各自已公布样本，不是全市场。增减项差基于当前榜单，不是固定会员组的连续变化。仅使用快照当日排名，未生成席位连续迁移或历史净多分位。</p><p>已取得的库存、仓单及产业统计在交叉核对区独立展示，不计入盘面标签。现货基差、连续订单与真实资金流仍不完整，不给供需缺口或资金流向定论。数据截至 ${DATA.asOf}；本页日收益采用昨收基准，原“市场概览”的日涨跌仍采用昨结算基准。</p></div></div></article>`}
