// Render acquired, dated series. Source links and research templates are not data.
function liveInventory(m){return LIVE_FUNDAMENTALS.inventories.filter(s=>s.code===m.code&&s.history?.length).sort((a,b)=>(a.metric==='stock'?0:1)-(b.metric==='stock'?0:1)||a.provider.localeCompare(b.provider))}
function liveSupply(m){return LIVE_FUNDAMENTALS.supplies.filter(s=>s.appliesTo?.[m.code]&&s.history?.length)}
function liveMetric(s){return s.metric==='stock'?'交易所库存小计':'注册仓单数量'}
function liveAge(date){return Math.floor((Date.parse(LIVE_FUNDAMENTALS.asOf+'T00:00:00Z')-Date.parse(date+'T00:00:00Z'))/86400000)}
function liveSource(url,name){return `<a href="${esc(url)}" target="_blank" rel="noopener noreferrer">${esc(name)} ↗</a>`}
function liveSpark(s,title){
 const rows=s.history.slice(-30);if(rows.length<2)return '<p class="research-missing">仅有一个有效样本，暂不绘制历史趋势。</p>';
 const W=720,H=195,p={l:80,r:20,t:25,b:40},values=rows.map(v=>v.value),lo=Math.min(...values),hi=Math.max(...values),pad=(hi-lo||Math.max(1,hi*.01))*.15,min=Math.max(0,lo-pad),max=hi+pad;
 const start=Date.parse(rows[0].date),span=Date.parse(rows.at(-1).date)-start||1,x=r=>p.l+(Date.parse(r.date)-start)/span*(W-p.l-p.r),y=v=>p.t+(max-v)/(max-min)*(H-p.t-p.b);
 return `<svg class="domestic-curve inventory-history" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(title)}，${esc(s.unit)}，${rows[0].date}至${rows.at(-1).date}"><title>${esc(title)} / ${esc(s.unit)}</title>${[min,(min+max)/2,max].map(v=>`<line x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}"/><text x="${p.l-8}" y="${y(v)+4}" text-anchor="end">${num(v,1)}</text>`).join('')}<polyline points="${rows.map(r=>`${x(r)},${y(r.value)}`).join(' ')}"/>${rows.map(r=>`<circle cx="${x(r)}" cy="${y(r.value)}" r="3"><title>${r.date}：${num(r.value,2)} ${esc(s.unit)}</title></circle>`).join('')}<text x="${p.l}" y="${H-10}">${rows[0].date}</text><text x="${W-p.r}" y="${H-10}" text-anchor="end">${rows.at(-1).date}</text></svg>`;
}
function liveState(){const statuses=LIVE_FUNDAMENTALS.statuses||[],bad=statuses.filter(s=>s.status!=='ok');return `<details class="source-health"><summary>采集状态 · ${bad.length?'有来源未完整取得':'来源已校验'}</summary><p>检查时间：${esc(LIVE_FUNDAMENTALS.checkedAt)}。失败保留原有有效序列，失败日期不补零；数据日以每条序列为准。</p>${statuses.map(s=>`<p><strong>${esc(s.source)}</strong> · ${esc(s.status)}${s.latest?' · '+esc(s.latest):''}${s.error?' · '+esc(s.error):''}${s.errors?.length?' · '+s.errors.length+' 项未取得（保留已取得样本）':''}</p>`).join('')}</details>`}
function liveInventoryTable(series){return `<div class="table-wrap"><table class="market-table"><thead><tr><th>指标 / 范围</th><th>数据日</th><th>当期值</th><th>原单位</th><th>报告增减</th><th>来源</th></tr></thead><tbody>${series.map(s=>{const p=s.history.at(-1);return `<tr><td>${liveMetric(s)}<small class="metric-note">${esc(s.scope)}</small></td><td>${p.date}</td><td>${num(p.value,2)}</td><td>${esc(s.unit)}</td><td>${signed(p.change,2)}</td><td>${liveSource(p.sourceUrl||s.sourceUrl,(s.collectionRole==='primary'?'东方财富':s.provider))}</td></tr>`}).join('')}</tbody></table></div>`}
function liveInventoryArticle(m){
 const series=liveInventory(m),p=domesticProfile(m);if(!series.length)return domesticInventoryWithoutLive(m);
 return `<article class="dimension-article"><div class="eyebrow">PHYSICAL INVENTORY / 已取得实物数据</div><h3>${esc(m.name)} · 仓单与库存</h3><p class="dimension-summary">${series.length} 条独立序列；仓单、库存小计、仓库与厂库分别展示。</p><p class="research-date-notice">行情 ${DATA.asOf} · 采集目标 ${LIVE_FUNDAMENTALS.asOf}。库存周报更新频率不同于仓单日报；每条显示实际数据日。</p>${liveInventoryTable(series)}${series.map(s=>{const last=s.history.at(-1),previous=s.history.at(-2),age=liveAge(last.date),stale=age>(s.frequency==='weekly'?10:4);return `<section class="live-series"><div class="live-series-title"><h4>${liveMetric(s)} · ${esc(s.scope)}</h4><span class="badge">${esc((s.collectionRole==='primary'?'东方财富':s.provider))} / ${s.frequency==='weekly'?'周度':'日度'}</span></div><p>${last.date}：<strong>${num(last.value,2)} ${esc(s.unit)}</strong>，报告增减 ${signed(last.change,2)} ${esc(s.unit)}。${previous?`上一个已取得样本 ${previous.date}：${num(previous.value,2)} ${esc(s.unit)}。`:''}</p>${stale?`<p class="research-gap">数据已有 ${age} 天未取得新值，请先复核来源；保留旧值而不标为最新。</p>`:''}${liveSpark(s,liveMetric(s)+' · '+s.scope)}<details><summary>历史明细 · ${s.history.length} 个有效样本</summary><div class="table-wrap"><table class="market-table"><thead><tr><th>日期</th><th>数量 / ${esc(s.unit)}</th><th>报告增减</th></tr></thead><tbody>${s.history.slice().reverse().map(h=>`<tr><td>${h.date}</td><td>${num(h.value,2)}</td><td>${signed(h.change,2)}</td></tr>`).join('')}</tbody></table></div></details><p class="dimension-provenance">${liveSource(last.sourceUrl||s.sourceUrl,(s.collectionRole==='primary'?'东方财富':s.provider))}。${esc(s.unitNote||'使用来源原单位，未折算重量。')}${esc(s.dateValidation||'报告日期或记录日期校验。')}${esc(s.note||'')}</p></section>`}).join('')}<div class="research-gap"><strong>口径说明</strong><p>注册仓单不等于全部实物库存；上期所库存“小计”包含已注册及符合交割品质但未注册的货物，两者不能相加。仓库与厂库不与分项重复合计，不跨交易所合并；东方财富与既有官方历史序列分别保留。</p><p>尚未取得连续社会库存、企业原料/成品库存。仓单注销不等于消费，仓单增加不等于产量增加，期货持仓不是库存。</p></div>${p?.inventoryFacts?.length?`<details><summary>此前报告观察（按原日期保留）</summary>${domesticFactCards(p.inventoryFacts)}</details>`:''}${m.code==='cu'?'<details class="legacy-research"><summary>用户LME铜截图 · 历史参考</summary>'+legacyDimensionArticle(m,2)+'</details>':''}${liveState()}</article>`;
}
const domesticInventoryWithoutLive=domesticInventoryArticle;
domesticInventoryArticle=liveInventoryArticle;
function liveSupplyArticle(m){
 const ss=liveSupply(m);if(!ss.length)return domesticSupplyWithoutLive(m);
 const p=domesticProfile(m),actual=ss.filter(s=>s.kind==='实际统计'),forecast=ss.filter(s=>s.kind==='年度预测');
 return `<article class="dimension-article"><div class="eyebrow">DOMESTIC SUPPLY / 自动采集的官方资料</div><h3>${esc(m.name)} · 国内供需证据</h3><p class="dimension-summary">已取得 ${actual.length} 项月度统计、${forecast.length} 项年度预测。单品数据、产业链关联和终端代理按各自范围展示。</p><p class="research-date-notice">检查时间 ${esc(LIVE_FUNDAMENTALS.checkedAt)}；盘面 ${DATA.asOf}。月度统计期不是发布日期，不用于当日涨跌归因或回测。</p>${ss.map(s=>{const h=s.history.at(-1),age=liveAge(h.date),stale=s.frequency==='monthly'&&age>80;return `<section class="live-series"><div class="live-series-title"><h4>${esc(s.label)}</h4><span class="badge">${esc(s.kind)}</span></div><p class="live-applicability">与本品种关系：${esc(s.appliesTo[m.code])}</p><strong class="live-value">${num(h.value,2)} <small>${esc(s.unit)}</small></strong><p>${esc(h.period||h.date)}${h.yoy!=null?' · 同比 '+signed(h.yoy,2)+'%':''}${h.revision!=null?' · 较上一报告预测修订 '+signed(h.revision,2)+' '+esc(s.unit):''}</p>${stale?'<p class="research-gap">统计期距当前目标日超过80天，待取得新一期；不将旧值当作当前供需。</p>':''}${liveSpark(s,s.label)}<details><summary>已取得的历史明细</summary><div class="table-wrap"><table class="market-table"><thead><tr><th>统计期 / 预测版本</th><th>数量 / ${esc(s.unit)}</th><th>${s.kind==='年度预测'?'上一报告预测':'同比 / %'}</th></tr></thead><tbody>${s.history.slice().reverse().map(r=>`<tr><td>${esc(r.period||r.date)}</td><td>${num(r.value,2)}</td><td>${r.previous!=null?num(r.previous,2):r.yoy!=null?signed(r.yoy,2):'未取得'}</td></tr>`).join('')}</tbody></table></div></details><p class="dimension-provenance">${liveSource(h.sourceUrl||s.sourceUrl,(s.collectionRole==='primary'?'东方财富':s.provider))} · 发布日期：${h.publishedAt||'接口未提供'}。${esc(s.scope)}。${esc(s.note)}</p></section>`}).join('')}<h4>库存交叉验证</h4>${liveInventory(m).length?liveInventoryTable(liveInventory(m)):'<p>本品种实物库存序列暂未取得，不能以期货持仓替代。</p>'}<div class="research-gap"><strong>研究解读与尚缺证据</strong><p>先分别比较本品种产出、下游加工和库存的变化；上游增产与下游加工增长并不必然同步。关联产品和终端产量只提供线索，不能直接换算本品种消费，也不足以计算供需缺口。</p><p>仍需补充连续的企业开工、订单、进口到港、成交提货与社会库存。月度生产和年度预测不能替代这些周度或日度证据。</p><p>海外补充：${esc(p.overseas)}</p></div><details><summary>此前人工核对资料（按原统计期保留）</summary>${domesticFactCards([...new Set([...p.supplyFacts,...p.demandFacts])])}</details>${liveState()}</article>`;
}
const domesticSupplyWithoutLive=domesticSupplyArticle;
domesticSupplyArticle=liveSupplyArticle;
const liveDetailBase=researchDetail;
researchDetail=function(){let html=liveDetailBase();const m=selected();if(liveSupply(m).length)html=html.replace(/(<button role="tab" id="dimension-tab-1"[\s\S]*?<small>)[^<]*(<\/small>)/,'$1官方数据$2');if(liveInventory(m).length)html=html.replace(/(<button role="tab" id="dimension-tab-2"[\s\S]*?<small>)[^<]*(<\/small>)/,'$1实物序列$2');return html};
const liveHomeBase=productResearchHome;
productResearchHome=function(){liveHomeBase();const host=$('.product-research-home');if(!host)return;const covered=DATA.markets.filter(m=>liveInventory(m).length).length,supply=DATA.markets.filter(m=>liveSupply(m).length).length;host.insertAdjacentHTML('afterbegin',`<div class="live-coverage"><strong>实物序列 ${covered} / ${DATA.markets.length} 品种（${DATA.markets.filter(m=>liveInventory(m).some(s=>s.history.at(-1).date===LIVE_FUNDAMENTALS.asOf)).length} 个有目标日数据） · 国内统计 ${supply} / ${DATA.markets.length} 品种</strong><span>目标 ${LIVE_FUNDAMENTALS.asOf} · 东方财富更新；既有官方历史保留原来源和日期，覆盖不代表完整供需平衡表。</span></div>`);const foot=host.querySelector('.chart-note');if(foot)foot.textContent=`盘面 ${DATA.asOf}；东方财富仓单随每日任务检查，未接入的库存和国内统计保留原统计期。人工研究资料保留原日期；相对强度仍以原始全市场样本计算。`;host.querySelectorAll('[data-product]').forEach(b=>{const m=DATA.markets.find(m=>m.code===b.dataset.product),label=b.querySelector('.product-research-state');if(label)label.textContent=`供需 ${liveSupply(m).length?'有统计':'资料线索'} · 库存 ${liveInventory(m).length?'有序列':'未取得'}`});};

// Describe the moving-average state, daily price action and distance separately.
// A rebound is an observed close-to-close move, not a trend reversal forecast.
function trendContextMarkup(m){
 const t=trend(m),a=m.analysis||{},day=a.return1,d=deviationObservation(a);
 const meanLabel=(a.priceBasis?'后复权':'')+({bull:'均线偏多',bear:'均线偏空',mixed:'均线分化'}[t.id]||t.name);
 const dayLabel=!Number.isFinite(day)?'昨收比较缺失':day===0?'当日持平':day>0?(t.id==='bear'?'当日反弹':'当日上涨'):(t.id==='bull'?'当日回落':'当日下跌');
 const dayText=dayLabel+(Number.isFinite(day)?' '+signed(day,2)+'% · 连续较昨收':'');
 const distance=Number.isFinite(a.distanceAtr20)?`距 MA20 ${signed(a.distanceAtr20,2)} ATR`:'均值偏离样本不足';
 return `<div class="trend-context" aria-label="${esc(m.name)}均线与短线观察"><span class="badge ${t.class}" title="${esc(a.asOf||m.main.date)}：后复权研究价与MA5相对MA20的位置；不预测下一交易日">${esc(meanLabel)}</span><strong class="trend-day ${Number.isFinite(day)?color(day):''}">${esc(dayText)}</strong>${a.liquidity?.low?'<small class="research-quality-note">低流动性 · 谨慎解读</small>':''}${a.deviationEpisode?`<small class="episode-summary">${esc(a.deviationEpisode.phase)} · 首次观察 ${esc(a.deviationEpisode.firstAt)}</small>`:''}${d?`<span class="trend-distance">${esc(d.label)} ${esc(signed(a.distanceAtr20,2))} ATR · ${esc(d.focus)}</span><small class="metric-note">偏离不代表必然反转</small>`:`<span class="trend-distance">${esc(distance)}</span>`}</div>`;
}
const trendContextTableBase=table;
table=function(){
 trendContextTableBase();
 const markets=new Map(DATA.markets.map(m=>[m.code,m]));
 document.querySelectorAll('#market-body [data-row]').forEach(row=>{const m=markets.get(row.dataset.row);if(m&&row.cells[7])row.cells[7].innerHTML=trendContextMarkup(m)});
};
const trendContextShellBase=tableShell;
tableShell=function(){return trendContextShellBase().replace('<th>趋势状态</th>','<th>均线 / 短线观察</th>').replace('红涨绿跌 · 点击品种查看价格与席位结构','日涨跌幅较昨结；短线观察较昨收 · 点击品种查看详情')};
const trendContextViewBase=trends;
trends=function(){return trendContextViewBase().replace("趋势偏多","均线偏多").replace("趋势偏空","均线偏空").replace('这里的趋势标签是本站透明规则的计算结果：使用当前代表合约的历史收盘价，短周期 MA5、中周期 MA20。它并非实际 CTA 基金仓位，也不是参考站的专有模型。','均线与偏离使用固定基准比例后复权连续价；报价列仍为真实代表合约。均线状态描述后复权收盘、MA5与MA20的位置；短线观察独立显示当日反弹或回落。偏离MA20达到2 ATR时另列反弹或回调观察，尚未达到门槛也会显示实际偏离。反弹不等于趋势反转，均线偏空也不代表排除反弹。表格日涨跌幅采用昨结算价，短线观察采用连续研究对应合约的昨收盘价，两个基准分别展示。')};

// Independent evidence, never an extra vote in the price/position label.
function researchInventoryChecks(m){
 const price=new Map((m.history||[]).filter(p=>p.contract===m.main.contract&&p.date<=DATA.asOf&&Number.isFinite(p.close)&&p.close>0).map(p=>[p.date,p.close]));
 return liveInventory(m).map(s=>{
  const points=s.history.filter(p=>p.date<=DATA.asOf&&Number.isFinite(p.value)),last=points.at(-1),previous=points.at(-2);
  if(!last)return null;
  const delta=previous?last.value-previous.value:null,firstPrice=previous?price.get(previous.date):null,lastPrice=price.get(last.date);
  const priceReturn=firstPrice!=null&&lastPrice!=null?(lastPrice/firstPrice-1)*100:null;
  let observation=s.metric==='stock'?'同口径库存变化，不能单独区分需求与供给影响。':'仓单注册与注销不是终端消费，不能直接判定供需方向。';
  if(s.metric==='stock'&&priceReturn!=null&&delta!==null){
   observation=priceReturn>0&&delta<0?'同区间价格上涨、该口径去库：方向相容，仍需区分需求改善与供应减少。':
    priceReturn<0&&delta>0?'同区间价格下跌、该口径累库：方向相容，仍需核对到货与实际需求。':
    priceReturn>0&&delta>0?'同区间价格上涨、该口径累库：存在交叉核对线索，需检查到货、需求和预期。':
    priceReturn<0&&delta<0?'同区间价格下跌、该口径去库：存在交叉核对线索，需检查供应收缩及库存转移。':'价格或库存持平，不形成方向性对应。';
  }
  return {series:s,last,previous,delta,priceReturn,observation};
 }).filter(Boolean);
}
function researchFundamentalCheck(m){
 const checks=researchInventoryChecks(m),supplies=liveSupply(m),actual=supplies.filter(s=>s.kind==='实际统计'),forecast=supplies.filter(s=>s.kind==='年度预测');
 const inventoryHtml=checks.map(c=>{const s=c.series;return `<article class="fundamental-fact"><span class="badge">${s.metric==='stock'?'实物库存':'仓单 · 注册口径'}</span><h4>${esc(s.scope)} · ${esc(s.provider)}</h4><p>${c.previous?esc(c.previous.date)+' → ':''}${esc(c.last.date)}：${num(c.last.value,2)} ${esc(s.unit)}${c.delta!==null?'；相邻已取得样本变化 '+signed(c.delta,2)+' '+esc(s.unit):'；仅一个样本，无法计算变化'}。</p><p>${c.priceReturn!==null?'同一固定合约、相同日期的收盘变化 '+signed(c.priceReturn,2)+'%。':'缺少同日期的固定合约价格端点，不拼接其他日期或合约。'}</p><p>${esc(c.observation)}</p><p>${liveSource(c.last.sourceUrl||s.sourceUrl,s.provider)} · ${s.frequency==='weekly'?'周度':'日度'} · 仅该来源范围，不汇总不同口径。</p></article>`}).join('');
 const supplyHtml=supplies.map(s=>{const h=s.history.at(-1);return `<article class="fundamental-fact"><span class="badge">${esc(s.kind)}</span><h4>${esc(s.label)}</h4><p>${esc(h.period||h.date)}：${num(h.value,2)} ${esc(s.unit)}${h.yoy!=null?'；同比 '+signed(h.yoy,2)+'%':''}。</p><p>与本品种关系：${esc(s.appliesTo[m.code])}。${s.kind==='年度预测'?'预测修订不等于已实现产销。':'加工、终端及行业代理不能等同单品实际消费。'}</p><p>${liveSource(h.sourceUrl||s.sourceUrl,s.provider)} · 发布：${esc(h.publishedAt||'接口未提供，不能回填为当时已知信息')}</p></article>`}).join('');
 return `<section class="fundamental-crosscheck"><div class="eyebrow">INDEPENDENT EVIDENCE / 独立交叉核对</div><h3>基本面验证 · 部分证据，尚不能形成综合多空结论</h3><p>盘面标签描述后复权连续均线与真实合约价仓、席位样本，指标存在重复价格信息，不是三份独立证据。本区另行对照实物及产业资料，不将库存升降机械换算成利多或利空。</p><p class="research-date-notice">行情 ${DATA.asOf}；资料检查 ${esc(LIVE_FUNDAMENTALS.checkedAt)}。${checks.length} 条库存/仓单口径，${actual.length} 项自动采集实际统计、${forecast.length} 项年度预测。人工资料仍在供需维度按原日期展示。采集时间不是发布时间；后续采集或修订资料不能作为历史回测当时已知信息。</p><h4>库存与同区间价格</h4><div class="fundamental-facts">${inventoryHtml||'<p>没有可与行情日期对齐的实物库存或仓单样本。</p>'}</div><details><summary>产业统计与需求代理 · ${supplies.length} 项</summary><div class="fundamental-facts">${supplyHtml||'<p>自动采集的单品统计暂缺，可到供需页查看人工资料及其原日期。</p>'}</div></details><div class="research-gap"><strong>还缺什么，才能验证研究判断</strong><p>${esc(domesticProfile(m)?.missing||'同口径连续的需求、现货基差及订单资料。')}</p><p>局部交易所库存、仓单与行业产量不能构成全市场供需平衡表。基本面未完整验证时，保留分歧，不提高盘面标签的置信度。</p></div></section>`;
}
const qualityDetailBase=researchDetail;
researchDetail=function(){
 const m=selected(),a=m.analysis;
 const quality=a.liquidity?.low?`<div class="research-gap"><strong>低流动性 · 盘面结果谨慎解读</strong><p>代表合约当日成交 ${num(a.liquidity.volume)} 手、持仓 ${num(a.liquidity.oi)} 手。${esc(a.liquidity.rule)}。保留原始数据，不把稀疏成交与活跃品种的参考价值等同。</p></div>`:'';
 const html=qualityDetailBase(),marker='<div class="factor-grid">',evidence=quality+researchFundamentalCheck(m);
 return html.includes(marker)?html.replace(marker,evidence+marker):html+evidence;
};
const qualityTableBase=researchTable;
researchTable=function(){
 qualityTableBase();
 const lookup=new Map(DATA.markets.map(m=>[m.code,m]));
 document.querySelectorAll('#research-body [data-research-row]').forEach(row=>{
  const a=lookup.get(row.dataset.researchRow)?.analysis;
  if(a?.liquidity?.low)row.cells[0].insertAdjacentHTML('beforeend','<small class="research-quality-note">低流动性 · 谨慎解读</small>');
 });
};

function continuousStudyPlot(m){
 const c=m.continuous;if(c?.status!=='ready'||c.history.length<2)return '';
 const all=c.history,offset=Math.max(0,all.length-60),rows=all.slice(offset).map((p,i)=>({...p,
  ma5:offset+i>=4?mean(all.slice(offset+i-4,offset+i+1).map(r=>r.close)):null,
  ma20:offset+i>=19?mean(all.slice(offset+i-19,offset+i+1).map(r=>r.close)):null}));
 const W=720,H=250,p={l:65,r:20,t:25,b:40},values=rows.flatMap(r=>[r.close,r.ma5,r.ma20]).filter(Number.isFinite),lo=Math.min(...values),hi=Math.max(...values),pad=(hi-lo||1)*.1,min=lo-pad,max=hi+pad;
 const x=i=>p.l+i/(rows.length-1)*(W-p.l-p.r),y=v=>p.t+(max-v)/(max-min)*(H-p.t-p.b);
 const path=key=>rows.map((r,i)=>Number.isFinite(r[key])?`${i===0||!Number.isFinite(rows[i-1][key])?'M':'L'}${x(i)},${y(r[key])}`:'').join(' ');
 return `<svg class="continuous-study-plot" viewBox="0 0 ${W} ${H}" role="img" aria-label="${esc(m.name)}固定基准比例后复权研究价及MA5、MA20，非实际成交报价"><title>后复权研究价：实线；MA5：橙色；MA20：虚线</title>${[min,(min+max)/2,max].map(v=>`<line x1="${p.l}" x2="${W-p.r}" y1="${y(v)}" y2="${y(v)}" stroke="var(--line)"/><text x="${p.l-6}" y="${y(v)+4}" text-anchor="end">${num(v,2)}</text>`).join('')}<path d="${path('close')}" fill="none" stroke="var(--accent)" stroke-width="2"/><path d="${path('ma5')}" fill="none" stroke="var(--amber)"/><path d="${path('ma20')}" fill="none" stroke="var(--muted)" stroke-dasharray="5 4"/>${[0,rows.length-1].map(i=>`<text x="${x(i)}" y="${H-12}" text-anchor="${i?'end':'start'}">${rows[i].date}</text>`).join('')}</svg>`;
}
function continuousStudySummary(m){
 const c=m.continuous,p=m.analysis.priceBasis;
 if(!c||!p)return '';
 if(!p.available)return `<section class="continuous-study research-gap"><strong>后复权连续研究数据不足</strong><p>最近已核实 ${esc(c.latest||'未取得')}；${esc(c.error||'当前尚无可核实的连续序列')}。连续指标留空，真实合约 ${esc(m.main.contract.toUpperCase())} 的报价、持仓及席位仍可查看。</p></section>`;
 return `<section class="continuous-study"><h3>价格研究口径 · 固定基准比例后复权</h3><p>基准 ${esc(c.baseDate)} / ${esc(c.baseContract.toUpperCase())} / ${num(c.basePrice,2)}；研究对应合约 ${esc(p.contract.toUpperCase())}，当前因子 ${num(p.factor,6)}。报价及量仓对应真实代表合约 ${esc(m.main.contract.toUpperCase())}；两者分别标注。</p><p>${esc(c.provider)}。依据前日持仓，远月超过当前合约1.1倍后于下一交易日切换，不回切；新因子＝旧因子×前日旧合约收盘÷前日新合约收盘。后复权研究价不等于实际报价或策略收益。</p><details><summary>后复权连续走势图 · 最近 ${Math.min(60,c.history.length)} / ${c.history.length} 个样本</summary>${continuousStudyPlot(m)}<p>蓝线为后复权研究价，橙线为MA5，虚线为MA20；OHLC统一应用同一因子，数量不复权。</p></details><details><summary>换月记录 · ${c.rollovers.length} 次</summary><div class="table-wrap"><table class="market-table"><thead><tr><th>切换日 / 比较日</th><th>旧 → 新</th><th>前日收盘（旧 / 新）</th><th>因子（前 → 后）</th><th>原始来源</th></tr></thead><tbody>${c.rollovers.map(r=>`<tr><td>${esc(r.date)}<small>${esc(r.comparisonDate)}</small></td><td>${esc(r.from.toUpperCase())} → ${esc(r.to.toUpperCase())}</td><td>${num(r.oldClose,2)} / ${num(r.newClose,2)}</td><td>${num(r.factorBefore,6)} → ${num(r.factorAfter,6)}</td><td>${[...new Set(r.sourceUrls.filter(Boolean))].map(url=>liveSource(url,'逐合约原始数据')).join(' · ')}</td></tr>`).join('')||'<tr><td colspan="5">本段观察内尚未发生换月。</td></tr>'}</tbody></table></div></details></section>`;
}
const continuousDetailBase=researchDetail;
researchDetail=function(){const html=continuousDetailBase(),summary=continuousStudySummary(selected());return html.replace('<div class="deviation-detail',summary+'<div class="deviation-detail')};
const actualSpark=spark;
spark=function(m,cls='mini-spark'){
 if(state.view!=='trends')return actualSpark(m,cls);
 if(m.continuous?.status!=='ready')return '<small class="metric-note">连续数据待补</small>';
 const rows=m.continuous.history.slice(-24),values=rows.map(r=>r.close);if(values.length<2)return '';
 const lo=Math.min(...values),range=Math.max(...values)-lo||1;
 return `<svg class="${cls}" viewBox="0 0 100 32" preserveAspectRatio="none" role="img" aria-label="${esc(m.name)}最近${values.length}个比例后复权连续研究样本"><polyline points="${values.map((v,i)=>`${i*100/(values.length-1)},${28-(v-lo)/range*24}`).join(' ')}" fill="none" stroke="var(--accent)" stroke-width="1.6" vector-effect="non-scaling-stroke"/></svg>`;
};
const continuousShellBase=tableShell;
tableShell=function(){let html=continuousShellBase();if(state.view==='trends')html=html.replace('近 24 样本','后复权走势');return html};
const continuousViewBase=trends;
trends=function(){const ready=DATA.markets.filter(m=>m.analysis.priceBasis?.available).length;return continuousViewBase().replace('<div class="coverage">',`<div class="coverage">后复权连续覆盖 ${ready} / ${DATA.markets.length}；对应行情日 ${DATA.asOf}。研究价不作为实际成交报价。`)};

